const referenceStudies=[...document.querySelectorAll('.reference-study')];if(referenceStudies.length){const motionAllowed=!matchMedia('(prefers-reduced-motion: reduce)').matches;const setStudyState=(study,active)=>{study.classList.toggle('is-paused',!active);const video=study.querySelector('video');if(video){if(active&&motionAllowed)video.play().catch(()=>study.classList.add('media-fallback'));else video.pause()}};const observer=new IntersectionObserver(entries=>entries.forEach(entry=>setStudyState(entry.target,entry.isIntersecting&&!document.hidden)),{rootMargin:'120px 0px',threshold:.08});referenceStudies.forEach(study=>{observer.observe(study);let tx=50,ty=50,cx=50,cy=50,raf=0;const render=()=>{cx+=(tx-cx)*.09;cy+=(ty-cy)*.09;study.style.setProperty('--mx',`${cx}%`);study.style.setProperty('--my',`${cy}%`);if(Math.abs(tx-cx)+Math.abs(ty-cy)>.1)raf=requestAnimationFrame(render);else raf=0};study.addEventListener('pointermove',event=>{const box=study.getBoundingClientRect();tx=((event.clientX-box.left)/box.width)*100;ty=((event.clientY-box.top)/box.height)*100;if(!raf)raf=requestAnimationFrame(render)});study.addEventListener('pointerleave',()=>{tx=50;ty=50;if(!raf)raf=requestAnimationFrame(render)})});document.addEventListener('visibilitychange',()=>referenceStudies.forEach(study=>setStudyState(study,!document.hidden&&study.getBoundingClientRect().bottom>0&&study.getBoundingClientRect().top<innerHeight)))}
